import{_ as a,o as e,c as i,a2 as s}from"./chunks/framework.F7eQ-ohH.js";const r="/bzygq/assets/quesion_imgs_image_1765976750391_0_1765976750392_34.DC01dYEB.png",d="/bzygq/assets/quesion_imgs_image_1765976751402_1_1765976751403_99.DGD8axY0.png",l="/bzygq/assets/quesion_imgs_image_1765976751803_2_1765976751803_93.CkwE_ycQ.png",_=JSON.parse('{"title":"哈希表基础概念","description":"","frontmatter":{},"headers":[],"relativePath":"科技岗专业课/数据结构/5、哈希表（了解）.md","filePath":"科技岗专业课/数据结构/5、哈希表（了解）.md","lastUpdated":1788881428000}'),n={name:"科技岗专业课/数据结构/5、哈希表（了解）.md"};function h(o,t,p,c,b,g){return e(),i("div",null,[...t[0]||(t[0]=[s(`<h1 id="哈希表基础概念" tabindex="-1">哈希表基础概念 <a class="header-anchor" href="#哈希表基础概念" aria-label="Permalink to &quot;哈希表基础概念&quot;">​</a></h1><h2 id="什么是哈希表" tabindex="-1">什么是哈希表？ <a class="header-anchor" href="#什么是哈希表" aria-label="Permalink to &quot;什么是哈希表？&quot;">​</a></h2><p>哈希表（Hash Table）是一种通过键值对（Key-Value Pair）存储数据的数据结构，其核心特性是能在平均O(1)时间复杂度内完成数据的插入、删除和查找操作， 核心组件如下：</p><table tabindex="0"><thead><tr><th>组件</th><th>作用</th></tr></thead><tbody><tr><td>键（Key）</td><td>数据的唯一标识符（如学号、身份证号）</td></tr><tr><td>值（Value）</td><td>与键关联的数据（如学生姓名、用户信息）</td></tr><tr><td>哈希函数</td><td>将键转换为数组索引的算法：index = hash(key) % capacity</td></tr><tr><td>桶（Bucket）</td><td>存储键值对的数组单元</td></tr></tbody></table><h2 id="哈希表-vs-数组-链表" tabindex="-1">哈希表 vs 数组/链表 <a class="header-anchor" href="#哈希表-vs-数组-链表" aria-label="Permalink to &quot;哈希表 vs 数组/链表&quot;">​</a></h2><table tabindex="0"><thead><tr><th>操作</th><th>哈希表（平均）</th><th>数组/链表</th></tr></thead><tbody><tr><td>插入</td><td>O(1)</td><td>O(1)（尾部插入）</td></tr><tr><td>查询</td><td>O(1)</td><td>O(n)（遍历查找）</td></tr><tr><td>删除</td><td>O(1)</td><td>O(n)（查找+删除）</td></tr></tbody></table><h1 id="哈希函数设计" tabindex="-1">哈希函数设计 <a class="header-anchor" href="#哈希函数设计" aria-label="Permalink to &quot;哈希函数设计&quot;">​</a></h1><h2 id="哈希函数的作用" tabindex="-1">哈希函数的作用 <a class="header-anchor" href="#哈希函数的作用" aria-label="Permalink to &quot;哈希函数的作用&quot;">​</a></h2><p>将任意大小的输入（键）映射到固定范围的输出（数组索引），其设计原则如下：</p><ol><li><strong>确定性</strong>：相同键必须产生相同索引。</li><li><strong>均匀性</strong>：键应均匀分布到所有桶中。</li><li><strong>高效性</strong>：计算速度快，避免复杂运算。</li></ol><h2 id="哈希函数实现示例" tabindex="-1">哈希函数实现示例 <a class="header-anchor" href="#哈希函数实现示例" aria-label="Permalink to &quot;哈希函数实现示例&quot;">​</a></h2><ul><li>简单哈希算法</li></ul><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>def simple_hash(key: int, capacity: int) -&gt; int:</span></span>
<span class="line"><span>    return key % capacity  # 对容量取模</span></span></code></pre></div><ul><li>字符串哈希算法（乘法哈希）</li></ul><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>def string_hash(s: str, capacity: int) -&gt; int:</span></span>
<span class="line"><span>    hash_value = 0</span></span>
<span class="line"><span>    for char in s:</span></span>
<span class="line"><span>        hash_value = (hash_value * 31 + ord(char)) % capacity</span></span>
<span class="line"><span>    return hash_value</span></span></code></pre></div><h1 id="哈希冲突与解决方案" tabindex="-1">哈希冲突与解决方案 <a class="header-anchor" href="#哈希冲突与解决方案" aria-label="Permalink to &quot;哈希冲突与解决方案&quot;">​</a></h1><h2 id="哈希冲突的原因" tabindex="-1">哈希冲突的原因 <a class="header-anchor" href="#哈希冲突的原因" aria-label="Permalink to &quot;哈希冲突的原因&quot;">​</a></h2><p>当不同键通过哈希函数映射到同一索引时发生冲突，根本原因是输入空间（键）远大于输出空间（桶数量）。</p><h2 id="解决方案" tabindex="-1">解决方案 <a class="header-anchor" href="#解决方案" aria-label="Permalink to &quot;解决方案&quot;">​</a></h2><h3 id="链式地址-separate-chaining" tabindex="-1">链式地址（Separate Chaining） <a class="header-anchor" href="#链式地址-separate-chaining" aria-label="Permalink to &quot;链式地址（Separate Chaining）&quot;">​</a></h3><p><img src="`+r+'" alt=""></p><ul><li><strong>原理</strong>：每个桶存储一个链表（或其他结构），冲突元素追加到链表。</li><li><strong>操作复杂度</strong>：</li><li>插入：O(1)</li><li>查询/删除：O(k)（k为链表长度，理想情况下k≈n/m）</li></ul><h3 id="开放寻址-open-addressing" tabindex="-1">开放寻址（Open Addressing） <a class="header-anchor" href="#开放寻址-open-addressing" aria-label="Permalink to &quot;开放寻址（Open Addressing）&quot;">​</a></h3><ul><li><strong>原理</strong>：冲突时按探测规则（如线性探测）寻找下一个空桶。</li><li><strong>探测方法</strong>：</li></ul><ol><li><strong>线性探测</strong>：index = (hash(key) + i) % capacity（i=1,2,3...）</li></ol><p><img src="'+d+'" alt=""></p><ol start="2"><li><strong>平方探测</strong>：index = (hash(key) + i²) % capacity</li></ol><p><img src="'+l+'" alt=""></p><ol start="3"><li><strong>双重哈希</strong>：index = (hash1(key) + i * hash2(key)) % capacity</li></ol><h3 id="哈希表扩容-rehashing" tabindex="-1">哈希表扩容（Rehashing） <a class="header-anchor" href="#哈希表扩容-rehashing" aria-label="Permalink to &quot;哈希表扩容（Rehashing）&quot;">​</a></h3><ul><li><p>触发条件</p><ul><li><strong>负载因子（Load Factor）</strong>：λ = 元素数量 / 桶数量</li><li>Java默认阈值：λ ≥ 0.75时扩容至2倍。</li></ul></li><li><p>扩容步骤</p><ol><li>创建新桶数组（容量为原2倍）。</li><li>遍历旧桶中所有键值对，重新计算哈希值并插入新数组。</li><li>释放旧数组内存。</li></ol></li><li><p><strong>性能影响</strong>：扩容耗时O(n)，但分摊到每次操作仍为O(1)。</p></li></ul><h1 id="知识点速记" tabindex="-1">知识点速记 <a class="header-anchor" href="#知识点速记" aria-label="Permalink to &quot;知识点速记&quot;">​</a></h1><p>哈希表核心机制</p><table tabindex="0"><thead><tr><th>要点</th><th>关键内容</th></tr></thead><tbody><tr><td>定义</td><td>通过键值映射实现O(1)时间复杂度的增删查改操作</td></tr><tr><td>组成</td><td>哈希函数（计算索引） + 数组（存储键值对） + 冲突解决策略</td></tr><tr><td>性能对比</td><td>✅ 哈希表：增删查改均为O(1)</td></tr><tr><td>⚠️ 数组/链表：查询/删除需O(n)</td><td></td></tr></tbody></table><p>哈希冲突及处理</p><table tabindex="0"><thead><tr><th>冲突原因</th><th>解决方法</th></tr></thead><tbody><tr><td>不同key映射到同一索引</td><td>1. 链式地址：冲突元素用链表存储（Java HashMap实现）2. 开放寻址：线性探测/平方探测/多次哈希</td></tr></tbody></table><p>扩容机制</p><table tabindex="0"><thead><tr><th>触发条件</th><th>操作</th></tr></thead><tbody><tr><td>负载因子 &gt; 阈值（如0.75）</td><td>1. 扩容为原容量2倍</td></tr></tbody></table><ol start="2"><li>重新哈希所有元素 |</li></ol><p>哈希函数设计要点</p><table tabindex="0"><thead><tr><th>原则</th><th>说明</th></tr></thead><tbody><tr><td>模数选择</td><td>✅ 必须用质数（如97、101）→ 减少周期性冲突</td></tr><tr><td>均匀分布</td><td>哈希算法需让key均匀分布（如SHA-256）</td></tr><tr><td>真题示例</td><td>H(k) = k % P，P选质数（如97）→ 答案B</td></tr></tbody></table><h1 id="真题练习" tabindex="-1">真题练习 <a class="header-anchor" href="#真题练习" aria-label="Permalink to &quot;真题练习&quot;">​</a></h1><p>| 【国家电网2019：】设某散列表的长度为100,散列两数H(k)-k%P，则P通常情况下最好选择() A.99 B.97 C.91 D.93 答案:B 解析:在散列表的设计中，选择合适的哈希函数是非常重要的一步，它直接影响到散列表的性能。当使用取模运算作为哈希函数的一部分时（即 H(k)=k%PH(k)=k%P），选择一个合适的 PP 值尤为关键。理想情况下，PP 应该是一个素数，尤其是当散列表的大小不是素数时。这是因为，如果 PP 是一个素数，可以更好地分散键值，减少冲突的发生，从而提高散列表的效率。选项分析： A.99：99 不是素数，因此不是一个好的选择。 B.97：97 是一个素数，能够较好地分布键值，减少冲突。 C.91：91 不是素数（91=7<em>13），因此也不是一个好的选择。 D.93：93 不是素数（93=3</em>31），同样不是一个好的选择。 答案: B. 97。</p><table tabindex="0"><thead><tr><th>解析：选择一个接近散列表长度的素数可以最大化地利用散列表的空间，并有效地减少哈希冲突。</th></tr></thead></table>',44)])])}const k=a(n,[["render",h]]);export{_ as __pageData,k as default};
